update driver_account
set total_amount = total_amount + #{amount}, available_amount = available_amount + #{amount}, total_income_amount = total_income_amount + #{amount}
where driver_id = #{driverId}

update driver_account
set total_amount = total_amount + #{amount},
	lock_amount = lock_amount + #{amount},
	total_income_amount = total_income_amount + #{amount}
where driver_id = #{driverId}

update driver_account
set lock_amount = lock_amount - #{amount},
	available_amount = available_amount + #{amount}
where driver_id = #{driverId}

update driver_account
set available_amount = available_amount - #{amount},
	total_pay_amount = total_pay_amount + #{amount}
where driver_id = #{driverId}
